Here is a simple C program to solve the chess tournament pairing problem:

```c
#include <stdio.h>

int main() {
    int t, n, x;
    scanf("%d", &t);
    while(t--) {
        scanf("%d %d", &n, &x);
        if(x <= n) {
            printf("0\n");
        } else {
            int diff = x - n;
            printf("%d\n", diff);
        }
    }
    return 0;
}
```

