Creating a full chess program is a complex task that involves a lot of code and understanding of chess rules, game logic, and AI. However, I can provide you with a simple command-line version of a chess game where you can play against yourself. This game will not have AI, and you will need to input the moves manually.

Here's a basic implementation using a 2D list to represent the chessboard:

```python
# Chess game in Python
class ChessGame:
    def __init__(self):
        self.board = [
            ['bR', 'bN', 'bB', 'bQ', 'bK', 'bB', 'bN', 'bR'],
            ['bP', 'bP', 'bP', 'bP', 'bP', 'bP', 'bP', 'bP'],
            ['--', '--', '--', '--', '--', '--', '--', '--'],
            ['--', '--', '--', '--', '--', '--', '--', '--'],
            ['--', '--', '--', '--', '--', '--', '--', '--'],
            ['--', '--', '--', '--', '--', '--', '--', '--'],
            ['wP', 'wP', 'wP', 'wP', 'wP', 'wP', 'wP', 'wP'],
            ['wR', 'wN', 'wB', 'wQ', 'wK', 'wB', 'wN', 'wR']
        ]
        self.current_player = 'w'
        self.moves = {
            'P': self.move_pawn,
            'R': self.move_rook,
            'N': self.move_knight,
            'B': self.move_bishop,
            'Q': self.move_queen,
            'K': self.move_king
        }

    def print_board(self):
        for row in self.board:
            print(' '.join(row))
        print()

    def get_move(self):
        move = input(f"{self.current_player}'s turn: ")
        from_pos, to_pos = move.split('-')
        from_row, from_col = int(from_pos[1]) - 1, ord(from_pos[0]) - 97
        to_row, to_col = int(to_pos[1]) - 1, ord(to_pos[0]) - 97
        return (from_row, from_col), (to_row, to_col)

    def move(self):
        (from_row, from_col), (to_row, to_col) = self.get_move()
        piece = self.board[from_row][from_col]
        if piece[0] != self.current_player:
            print("Invalid move: That's not your piece!")
            return
        if piece[1] not in self.moves:
            print("Invalid move: Unknown piece!")
            return
        if not self.moves[piece[1]](from_row, from_col, to_row, to_col):
            print("Invalid move!")
            return
        self.board[to_row][to_col] = piece
        self.board[from_row][from_col] = '--'
        self.current_player = 'w' if self.current_player == 'b' else 'b'

    def move_pawn(self, from_row, from_col, to_row, to_col):
        if to_col != from_col:
            return False
        if self.current_player == 'w':
            if from_row != 1 and to_row != from_row + 1:
                return False
            if from_row == 1 and to_row not in [from_row + 1, from_row + 2]:
                return False
        if self.current_player == 'b':
            if from_row != 6 and to_row != from_row - 1:
                return False
            if from_row == 6 and to_row not in [from_row - 1, from_row - 2]:
                return False
        if self.board[to_row][to_col] != '--':
            return False
        return True

    def move_rook(self, from_row, from_col, to_row, to_col):
        if from_row == to_row or from_col == to_col:
            return True
        return False

    def move_knight(self, from_row, from_col, to_row, to_col):
        if abs(from_row - to_row) * abs(from_col - to_col) == 2:
            return True
        return False

    def move_bishop(self, from_row, from_col, to_row, to_col):
        if abs(from_row - to_row) == abs(from_col - to_col):
            return True
        return False

    def move_queen(self, from_row, from_col, to_row, to_col):
        return self.move_rook(from_row, from_col, to_row, to_col) or self.move_bishop(from_row, from_col, to_row, to_col)

    def move_king(self, from_row, from_col, to_row, to_col):
        if abs(from_row - to_row) <= 1 and abs(from_col - to_col) <= 1:
            return True
        return False


def main():
    game = ChessGame()
    while True:
        game.print_board()
        game.move()


if __name__ == "__main__":
    main()
```

This code creates a basic framework for a chess game, but it does not handle all chess rules, such as castling, en passant, check, and checkmate. You can expand this code to include these features and make it more sophisticated.

