const sliderCircle = document.getElementById('slider-circle');
const markerCircle = document.getElementById('marker-circle');
let radius = 50; // initial radius in percentage

sliderCircle.addEventListener('mousedown', function (event) {
  const rect = sliderCircle.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;
  const distance = Math.sqrt(x * x + y * y);
  const newRadius = distance / (rect.width / 2) * 100;

  if (newRadius >= 10 && newRadius <= 90) {
    radius = newRadius;
    adjustRadius();
  }
});

function adjustRadius() {
  sliderCircle.style.transform = `scale(${radius / 100})`;
  markerCircle.style.transform = `scale(${radius / 100}) translate(-50%, -50%)`;
}

adjustRadius(); // initial adjustment
```

### Step 4: Concentric Circle Markers

To add concentric circle markers at different radii, you can add more divs with the `slider-circle` class and adjust their CSS properties. Each circle can have a different border style or color to distinguish them.

