```php
<?php

namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;
use Illuminate\Support\Facades\Session;

class FavoritesManager
{
    public function addFavorite($name)
    {
        $user = Auth::user();
        if ($user) {
            // Save favorite to database for logged in user
            Favorite::create([
                'user_id' => $user->id,
                'name' => $name,
            ]);
        } else {
            // Save favorite to session for guest user
            $favorites = session('favorites', []);
            $favorites[] = $name;
            Session::put('favorites', $favorites);
        }
    }

    public function removeFavorite($name)
    {
        $user = Auth::user();
        if ($user) {
            // Remove favorite from database for logged in user
            Favorite::where('user_id', $user->id)
                    ->where('name', $name)
                    ->delete();
        } else {
            // Remove favorite from session for guest user
            $favorites = session('favorites', []);
            $key = array_search($name, $favorites);
            if ($key !== false) {
                unset($favorites[$key]);
                Session::put('favorites', $favorites);
            }
        }
    }

    public function hasFavorite($name)
    {
