To create a Metal compute kernel for Gaussian blurring an image, you'll need to follow these steps:

1. Set up a Metal device, command queue, and command buffer.
2. Create a Metal texture to hold the input image data.
3. Create a Metal texture to hold the output image data.
4. Write the compute kernel shader code for the Gaussian blur.
5. Set up the compute pipeline state object (PSO) using the shader code.
6. Encode the compute commands and execute the kernel on the GPU.

Here's an example of the compute kernel shader code for a Gaussian blur:

```metal
#include <metal_stdlib>
using namespace metal;

// Define the kernel function with a 1D texture as input and output
kernel void gaussianBlur(
    device const uint *inputTexture,  // Input texture
    const int2 inputTextureSize,      // Input texture size
    device float *outputTexture,      // Output texture
    const int2 outputTextureSize,     // Output texture size
    const float radius,               // Blur radius
    const float sigma,                // Blur sigma
    const int2 threadgroupSize,       // Threadgroup size
    uint gid[[thread_position_in_grid]])
{
    // Calculate the position in the input and output textures
    int2 position = gid % threadgroupSize;
    int2 threadgroupPosition = gid / threadgroupSize;
    int2 inputPosition = position + threadgroupPosition * threadgroupSize;

    // Initialize the output pixel color to zero
    float4 outputColor = 0.0f;

    // Calculate the Gaussian weight for the radius
    float weightSum = 0.0f;
    for (int i = -radius; i <= radius; i++)
    {
        float distance = (float)i * (float)i;
        float weight = exp(-distance / (2.0f * sigma * sigma));
        weightSum += weight;
        int2 samplePosition = inputPosition + int2(i, 0);

        // Wrap around the texture if necessary
        if (samplePosition.x < 0)
            samplePosition.x = inputTextureSize.x - 1;
        else if (samplePosition.x >= inputTextureSize.x)
            samplePosition.x = 0;

        // Add the weighted color to the output color
        outputColor += weight * float4(inputTexture[samplePosition.x * inputTextureSize.y + samplePosition.y]) / 255.0f;
    }

