function findEntity(jsonObj, entityKey) {
  let result = [];
  let recursiveSearch = (currentObj, path) => {
    if (typeof currentObj === 'object') {
      for (let key in currentObj) {
        let newPath = path.concat(key);
        if (key === entityKey) {
          result.push({
            value: currentObj[key],
            path: newPath
          });
        }
        recursiveSearch(currentObj[key], newPath);
      }
    }
  };
  recursiveSearch(jsonObj, []);
  return result;
}
