Creating a full Connect-4 game program in this text-based format would be quite extensive, but I can certainly help you understand how you might write one in Python. Here's a basic outline of a Connect-4 game program:

```python
import numpy as np

def create_board():
    board = np.zeros((6,7))
    return board

def drop_piece(board, row, col, piece):
    board[row][col] = piece

def is_valid_location(board, col):
    return board[5][col] == 0

def get_next_open_row(board, col):
    for r in range(6):
        if board[r][col] == 0:
            return r

def print_board(board):
    print(np.flip(board, 0))

def winning_move(board, piece):
    # Check horizontal locations for win
    for c in range(4):
        for r in range(6):
            if board[r][c] == piece and board[r][c+1] == piece and board[r][c+2] == piece and board[r][c+3] == piece:
                return True

    # Check vertical locations for win
    for c in range(7):
        for r in range(3):
            if board[r][c] == piece and board[r+1][c] == piece and board[r+2][c] == piece and board[r+3][c] == piece:
                return True

    # Check positively sloped diaganols
    for c in range(4):
        for r in range(3):
            if board[r][c] == piece and board[r+1][c+1] == piece and board[r+2][c+2] == piece and board[r+3][c+3] == piece:
                return True

    # Check negatively sloped diaganols
    for c in range(4):
        for r in range(3,6):
            if board[r][c] == piece and board[r-1][c+1] == piece and board[r-2][c+2] == piece and board[r-3][c+3] == piece:
                return True

def main():
    board = create_board()
    game_over = False
    turn = 0

    while not game_over:
        # Ask for Player 1 Input
        if turn == 0:
            col = int(input("Player 1 make your Selection (0-6): "))

            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, 1)

                if winning_move(board, 1):
                    print("Player 1 wins!!")
                    game_over = True

        # # Ask for Player 2 Input
        else:
            col = int(input("Player 2 make your Selection (0-6): "))

            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, 2)

                if winning_move(board, 2):
                    print("Player 2 wins!!")
                    game_over = True

        print_board(board)

        turn += 1
        turn = turn % 2

if __name__ == '__main__':
    main()
```

This program creates a 6x7 board, allows players to take turns to place their pieces, and checks for a winning condition after each move. Remember to run this code in a Python environment capable of handling numpy arrays for the board representation.

